package com.faka.invisible.tell

import com.faka.invisible.voicekit.*

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class TellRulesTest {
    private fun mv(c: String) = when (c) { "J" -> Move.JAB; "G" -> Move.GUARD; else -> Move.CHARGE }

    /** Generated by running yomi.resolve (e1 e2 l1 l2 m1 m2 -> e1 e2 l1 l2). Not hand-written. */
    private val table = listOf(
        "0 0 2 1 G G -> 1 1 2 1",
        "0 1 1 2 G J -> 2 1 1 1",
        "0 1 4 2 G G -> 1 2 4 2",
        "0 3 2 3 G J -> 2 3 2 2",
        "0 4 3 4 G C -> 1 2 1 4",
        "0 5 3 3 G C -> 1 3 1 3",
        "1 0 2 2 J G -> 1 2 1 2",
        "1 2 2 4 G J -> 3 2 2 3",
        "1 3 2 2 G G -> 2 4 2 2",
        "1 3 3 3 J C -> 1 1 3 2",
        "1 4 1 2 G J -> 3 4 1 1",
        "1 5 3 4 G G -> 2 5 3 4",
        "2 0 1 1 J G -> 2 2 0 1",
        "2 0 4 3 J G -> 2 2 3 3",
        "2 1 4 1 J J -> 2 1 3 0",
        "2 4 1 2 J J -> 2 4 0 1",
        "2 5 4 3 G C -> 3 3 2 3",
        "2 5 4 3 G J -> 4 5 4 2",
        "3 0 1 2 C G -> 1 1 1 0",
        "3 0 2 3 J G -> 3 2 1 3",
        "3 1 1 3 C J -> 1 1 0 3",
        "3 2 1 1 C G -> 1 3 1 -1",
        "3 2 3 2 J J -> 3 2 2 1",
        "3 3 1 2 J C -> 3 1 1 1",
        "3 3 4 1 J G -> 3 5 3 1",
        "3 3 4 3 J J -> 3 3 3 2",
        "3 3 4 4 J G -> 3 5 3 4",
        "3 4 2 3 C C -> 1 2 0 1",
        "3 4 2 3 C G -> 1 5 2 1",
        "3 4 2 3 C J -> 1 4 1 3",
        "3 4 2 3 G C -> 4 2 0 3",
        "3 4 2 3 G G -> 4 5 2 3",
        "3 4 2 3 G J -> 5 4 2 2",
        "3 4 2 3 J C -> 3 2 2 2",
        "3 4 2 3 J G -> 3 5 1 3",
        "3 4 2 3 J J -> 3 4 1 2",
        "3 4 3 2 G C -> 4 2 1 2",
        "3 5 1 1 C C -> 1 3 -1 -1",
        "4 1 3 4 J J -> 4 1 2 3",
        "4 2 2 1 C J -> 2 2 1 1",
        "4 2 4 1 J G -> 4 4 3 1",
        "4 3 4 1 J G -> 4 5 3 1",
        "4 4 1 4 C C -> 2 2 -1 2",
        "4 4 3 2 C J -> 2 4 2 2",
        "4 4 4 1 J J -> 4 4 3 0",
        "5 0 1 3 G G -> 5 1 1 3",
        "5 0 3 3 C G -> 3 1 3 1",
        "5 2 3 2 G J -> 5 2 3 1",
        "5 3 1 2 J J -> 5 3 0 1",
        "5 4 1 3 C J -> 3 4 0 3",
        "5 4 4 3 G C -> 5 2 2 3",
        "5 5 4 4 C C -> 3 3 2 2",
        "5 5 4 4 C G -> 3 5 4 2",
        "5 5 4 4 C J -> 3 5 3 4",
        "5 5 4 4 G C -> 5 3 2 4",
        "5 5 4 4 G G -> 5 5 4 4",
        "5 5 4 4 G J -> 5 5 4 3",
        "5 5 4 4 J C -> 5 3 4 3",
        "5 5 4 4 J G -> 5 5 3 4",
        "5 5 4 4 J J -> 5 5 3 3",
    )

    @Test fun matchesYomi() {
        assertEquals(60, table.size)
        for (line in table) {
            val (lhs, rhs) = line.split(" -> ")
            val a = lhs.split(" ")
            val b = rhs.split(" ").map { it.toInt() }
            val s = State(a[0].toInt(), a[1].toInt(), a[2].toInt(), a[3].toInt())
            val r = TellRules.resolve(s, mv(a[4]), mv(a[5]))
            assertEquals(line, State(b[0], b[1], b[2], b[3]), r.after)
        }
    }

    @Test fun fixAndLegal() {
        assertEquals(listOf(Move.GUARD), TellRules.legal(0))
        assertEquals(listOf(Move.JAB, Move.GUARD), TellRules.legal(2))
        assertEquals(Move.values().toList(), TellRules.legal(3))
        assertEquals(Move.GUARD, TellRules.fix(Move.CHARGE, 2))
        assertEquals(Move.GUARD, TellRules.fix(Move.JAB, 0))
        assertEquals(Move.JAB, TellRules.fix(Move.JAB, 1))
        val r = TellRules.resolve(State(0, 3, 4, 4), Move.CHARGE, Move.GUARD, 5)
        assertEquals(Move.GUARD, r.mine)
        assertEquals(5, r.no)
    }

    @Test fun flags() {
        val s = State(3, 3, 4, 4)
        val p = TellRules.resolve(s, Move.GUARD, Move.JAB)
        assert(p.myParry && !p.theirParry && p.damageToOpp == 1 && p.damageToMe == 0)
        val f = TellRules.resolve(s, Move.CHARGE, Move.JAB)
        assert(f.myChargeFizzled && f.damageToMe == 1 && f.damageToOpp == 0)
        val g = TellRules.resolve(s, Move.JAB, Move.CHARGE)
        assert(g.theirChargeFizzled && g.damageToOpp == 1)
        val t = TellRules.resolve(s, Move.GUARD, Move.JAB.let { Move.CHARGE })
        assert(t.damageToMe == 2 && !t.myParry)
    }

    @Test fun startState() = assertEquals(State(3, 3, 4, 4), TellRules.start())

    @Test fun finished() {
        assertNull(TellRules.finished(State(3, 3, 2, 2), 19))
        assertEquals(Result.WIN, TellRules.finished(State(3, 3, 3, 2), 20))
        assertEquals(Result.LOSS, TellRules.finished(State(3, 3, 1, 2), 20))
        assertEquals(Result.DRAW, TellRules.finished(State(3, 3, 2, 2), 20))
        assertEquals(Result.WIN, TellRules.finished(State(3, 3, 1, 0), 3))
        assertEquals(Result.LOSS, TellRules.finished(State(3, 3, 0, 1), 3))
        assertEquals(Result.DRAW, TellRules.finished(State(3, 3, 0, 0), 3))
    }
}
